  '            return self.overrides[relative]\n'
  '        return (self.root / self.relative).read_bytes()\n'
  '\n'
  "    def read_text(self, encoding='utf-8', errors='strict'):\n"
  '        return self.read_bytes().decode(encoding, errors)\n'
  '\n'
  "    def open(self, mode='r', *args, **kwargs):\n"
  "        require(mode in {'r', 'rb'}, 'Historical view is read-only')\n"
  "        return io.BytesIO(self.read_bytes()) if mode == 'rb' else io.StringIO(self.read_text())\n",
