  '    def test_schema_commands_use_exact_observed_result_paths_and_nine_bounded_reads(self):\n'
  "        paths = {'app-unit': Path('/synthetic/current-app.xcresult'), 'ui': "
  "Path('/synthetic/current-ui.xcresult')}\n"
  '        rows = runner.merchant_schema_commands(paths)\n'
  '        self.assertEqual(len(rows), 9)\n'
  "        self.assertEqual(rows[0][1], ['xcrun','xcresulttool','--version'])\n"
  "        self.assertEqual(rows[3][1], ['xcrun','simctl','list','devices','available','--json'])\n"
  "        self.assertEqual(rows[4][1], ['xcrun','simctl','list','runtimes','--json'])\n"
  '        for filename, command, bound in rows[5:]:\n'
  "            group = 'app-unit' if filename.startswith('app-unit') else 'ui'\n"
