def split404_layer(selection):
    require(type(selection) is dict and selection.get('club_member_route') == PRODUCT404_LAYER,
            'Changed fixed current649 source/partition contract')
    require(split404_hash(selection) == PRODUCT404_SELECTION_SHA256, 'Changed complete current649 selection')
    return PRODUCT404_LAYER['split']
def validate_split404_selection(selection, root):
    validate_product404_selection(selection, root)
    layer = split404_layer(selection)
    require([p['name'] for p in layer['partitions']] == list(SPLIT404_PARTITIONS), 'Changed exact three-partition order')
    flat = [m for p in layer['partitions'] for m in p['methods']]
    original = [m for g in selection['groups'] for m in g['methods']]
    require(len(flat) == len(set(flat)) == 649 and set(flat) == set(original), 'Partitions must cover all exact649 once')
    require([len(p['methods']) for p in layer['partitions']] == [340, 244, 65], 'Wrong fixed340/244/65 cardinality')
    require([len(g['methods']) for g in selection['groups']] == [340, 244, 65], 'Wrong complete current649 group counts')
    require(all(m.startswith(target+'/') for part,target in zip(layer['partitions'],('QuestifyCoreTests','QuestifyAppUnitTests','QuestifyUITests')) for m in part['methods']), 'Wrong partition target assignment')
    return selection

def split404_require_admission(selection):
    require(split404_layer(selection)['admission'] == 'AUTHORIZED_THREE_STANDARD_MACOS_DIAGNOSTIC_WORKERS',
            'Current649 split execution is not authorized by this fixed contract')


def verify_split404_scope(root, selection):
    validate_split404_selection(selection, root)
    split404_ensure_public_object(root, HISTORICAL_BASE_COMMIT)
    scope = verify_product404_scope(root, selection)
    return {k: scope[k] for k in ('source_sha', 'source_tree')}

def split404_hash(value):
    return hashlib.sha256(encode(value).encode()).hexdigest()


def split404_groups(selection, partition):
    require(partition in SPLIT404_PARTITIONS, 'Unknown exact partition')
    layer = split404_layer(selection)
    row = next(p for p in layer['partitions'] if p['name'] == partition)
    result = []
    for original in selection['groups']:
        methods = [m for m in row['methods'] if m.startswith(original['target'] + '/')]
        if methods:
            result.append(dict(original, methods=methods))
    return result


def split404_ensure_public_object(root, revision):
    """Only fixed historical objects, sanitized env, no credentials/redirects, 60s."""
    require(revision in SPLIT404_PUBLIC_OBJECTS,'Unapproved public historical object')
    tree=SPLIT404_PUBLIC_OBJECTS[revision]
    try:
        checked(['git','cat-file','-e',revision+'^{commit}'],root)
        actual=checked(['git','rev-parse',revision+'^{tree}'],root)
    except ValueError:
        actual=None
    if actual is not None:
        require(actual==tree,'Present historical object tree differs');return
    environment={'PATH':os.environ.get('PATH',os.defpath),'LANG':'C','HOME':'/dev/null',
        'GIT_TERMINAL_PROMPT':'0','GIT_CONFIG_NOSYSTEM':'1','GIT_CONFIG_GLOBAL':'/dev/null',
        'GIT_ASKPASS':'/usr/bin/false','SSH_ASKPASS':'/usr/bin/false'}
    code,raw=execute(['git','config','--local','--includes','--name-only','--list'],root,10,True,env=environment)
    require(code==0,'Cannot inspect exact public object configuration')
    require(not any(key.startswith(('url.','http.','credential.','include.','includeif.')) or
        key in {'core.askpass','extensions.worktreeconfig'} for key in raw.decode().lower().splitlines()),
        'Public historical fetch rejects credentials, redirects, and includes')
    command=['git','-c','credential.helper=','-c','core.askPass=','-c','http.extraHeader=',
        '-c','http.followRedirects=false','-c','protocol.allow=never','-c','protocol.https.allow=always',
        'fetch','--no-tags','--no-write-fetch-head','--depth=1','--no-recurse-submodules',
        'https://github.com/liboyang42-cpu/chengyin-ios.git',revision]
    code,_=execute(command,root,60,True,env=environment)
    require(code==0,'Exact historical object unavailable; no admission')
    checked(['git','cat-file','-e',revision+'^{commit}'],root)
    require(checked(['git','rev-parse',revision+'^{tree}'],root)==tree,'Fetched historical tree differs')


def split404_identity(root, selection, scope=None, environ=None):
    env = os.environ if environ is None else environ
    require(env.get('GITHUB_REPOSITORY') == 'liboyang42-cpu/chengyin-ios' and
            env.get('GITHUB_REF') == 'refs/heads/migration/native-ios' and
            env.get('GITHUB_EVENT_NAME') in {'push','workflow_dispatch'}, 'Wrong split404 run scope')
    for key in ('GITHUB_RUN_ID','GITHUB_RUN_ATTEMPT'):
        require(re.fullmatch('[1-9][0-9]*',env.get(key,'')) is not None,'Invalid run identity')
    scope = verify_split404_scope(root,selection) if scope is None else scope
    require(env.get('GITHUB_WORKFLOW_SHA') == scope['source_sha'] == env.get('GITHUB_SHA'), 'Workflow/source SHA differs')
    return dict(scope, repository=env['GITHUB_REPOSITORY'], ref=env['GITHUB_REF'], event=env['GITHUB_EVENT_NAME'],
        workflow_sha=env['GITHUB_WORKFLOW_SHA'], run_id=env['GITHUB_RUN_ID'], run_attempt=env['GITHUB_RUN_ATTEMPT'],
        selection_sha256=digest(root/SPLIT404_PATHS[1]), source_archive_sha256=split404_archive_digest(root,scope['source_sha']), partition_table_sha256=split404_hash(split404_layer(selection)['partitions']))


def split404_archive_digest(root, revision):
    """Bounded streaming identity, without persisting/transferring a source archive."""
    import selectors
    require(re.fullmatch('[a-f0-9]{40}', revision) is not None, 'Invalid archive revision')
    process = subprocess.Popen(['git','archive','--format=tar',revision], cwd=root,
        stdout=subprocess.PIPE, stderr=subprocess.DEVNULL, start_new_session=True)
    selector=selectors.DefaultSelector();selector.register(process.stdout,selectors.EVENT_READ)
    end=time.monotonic()+60;total=0;hasher=hashlib.sha256()
    try:
        while selector.get_map():
            remaining=end-time.monotonic();require(remaining>0,'Source archive identity timed out')
            for key,_ in selector.select(remaining):
                raw=os.read(key.fd,1024*1024)
                if not raw:selector.unregister(key.fileobj);continue
                total+=len(raw);require(total<=256*1024*1024,'Source archive identity exceeds bounded stream')
                hasher.update(raw)
        require(process.wait(timeout=max(0.1,end-time.monotonic()))==0 and total>0,'Source archive failed')
        return hasher.hexdigest()
    finally:
        selector.close();process.stdout.close()
        if process.poll() is None:
            os.killpg(process.pid,signal.SIGKILL);process.wait(timeout=5)


def split404_artifact_name(identity, partition):
    require(partition in SPLIT404_PARTITIONS,'Unknown partition artifact')
    return 'native-targeted-649-' + '-'.join([identity['source_sha'],identity['run_id'],identity['run_attempt'],partition])


def split404_phase_names(partition):
    require(partition in SPLIT404_PARTITIONS, 'Unknown exact target partition')
    common={'checkout-initialization','python-validation','source-validation','scope-before','toolchain-before','toolchain-after-build','products-before','products-after','scope-after','toolchain-after','report'}
    if partition=='core':return common|{'core-build','core-test'}
    return common|{'schema-capture','simulator-inventory','boot',('app-build' if partition=='app-unit' else 'ui-build'),('app-test' if partition=='app-unit' else 'ui-test')}


def split404_validate_phases(phases, partition):
    import math
    require(isinstance(phases,dict) and set(phases) == split404_phase_names(partition), 'Missing/unknown phase budget')
    for name, row in phases.items():
        require(isinstance(row,dict) and set(row) == {'started_monotonic','ended_monotonic','wall_seconds','returncode'}, 'Unknown phase schema')
        require(type(row['returncode']) is int and row['returncode'] == 0, 'Phase did not succeed: '+name)
        for key in ('started_monotonic','ended_monotonic','wall_seconds'):
            require(type(row[key]) in (int,float) and math.isfinite(row[key]) and row[key] >= 0, 'Invalid phase time')
        require(row['ended_monotonic'] >= row['started_monotonic'] and
                abs(row['ended_monotonic']-row['started_monotonic']-row['wall_seconds']) < 0.00001, 'Inconsistent phase time')


def split404_worker_clock(phases):
    start=phases['checkout-initialization']['started_monotonic'];end=phases['report']['ended_monotonic']
    phase_seconds=sum(row['wall_seconds'] for row in phases.values())
    return {'started_monotonic':start,'ended_monotonic':end,'wall_seconds':end-start,
            'classified_phase_seconds':phase_seconds,'unclassified_overhead_seconds':end-start-phase_seconds}


def split404_validate_worker_clock(receipt,phases):
    import math
    expected=split404_worker_clock(phases)
    require(receipt.get('worker_clock')==expected,'Worker total/overhead clock differs from phase observations')
    require(all(type(value) in (int,float) and math.isfinite(value) for value in expected.values()),'Invalid worker clock')
    require(0<=expected['wall_seconds']<=2700 and expected['unclassified_overhead_seconds']>=-0.00001,'Worker exceeds cap or overlapping phases')
    ordered=sorted(phases.values(),key=lambda row:row['started_monotonic'])
    require(all(a['ended_monotonic']<=b['started_monotonic']+0.00001 for a,b in zip(ordered,ordered[1:])),'Overlapping phase observations')


def split404_ledger(products):
    entries=[]; products=products.resolve(strict=True)
    for path in sorted(products.rglob('*')):
        relative=str(path.relative_to(products))
        if path.is_symlink():
            require(path.resolve(strict=True).is_relative_to(products),'Products link escaped build root')
            entries.append([relative,'link',os.readlink(path)])
        elif path.is_file(): entries.append([relative,'file',digest(path)])
    require(bool(entries),'Empty product ledger')
    return entries


def split404_validate_ledger(ledger, product):
    require(isinstance(ledger,list) and ledger,'Empty product ledger')
    names=[]
    for row in ledger:
        require(isinstance(row,list) and len(row)==3 and all(isinstance(v,str) for v in row),'Malformed product ledger')
        name,kind,value=row
        require(name and not Path(name).is_absolute() and '..' not in Path(name).parts and '\\' not in name,'Unsafe product ledger path')
        require(kind in ('file','link'),'Unknown product ledger entry')
        require(bool(re.fullmatch('[a-f0-9]{64}',value)) if kind=='file' else bool(value),'Invalid product entry identity')
        names.append(name)
    require(names==sorted(set(names)),'Duplicate/unsorted product ledger')
    require(type(product.get('files')) is int and product['files']==len(ledger) and product.get('sha256')==split404_hash(ledger),'Product ledger digest/count differs')
    if product.get('configuration')==SPLIT404_CONFIGS['core']:
        require(product.get('bundle')=='QuestifyCorePackageTests.xctest' and any(row[0]=='Contents/MacOS/QuestifyCorePackageTests' and row[1]=='file' for row in ledger),'Wrong Core executable inventory')
        return
    run=product.get('xctestrun')
    require(isinstance(run,str) and Path(run).name==run and run.endswith('.xctestrun'),'Invalid product xctestrun')
    require([run,'file',product.get('xctestrun_sha256')] in ledger,'Xctestrun not bound to product ledger')


def split404_evidence_names(partition):
    require(partition in SPLIT404_PARTITIONS, 'Unknown exact target partition')
    names={'receipt.json','phase-times.json','products-ledger.json'}
    if partition=='core':return names|{'core.xml','core-stdout.txt','core-build-provenance.json'}
    names|={'xcresult-summary-help.txt','xcresult-tests-help.txt','xcresult-version.txt','simulator-devices.json','simulator-runtimes.json','schema-manifest.json','xcresult-summary-schema.json','xcresult-tests-schema.json',partition+'-summary.json',partition+'-tests.json'}
    names|={'app-unit-manifest.json'} if partition=='app-unit' else {'ui-config.json','ui-info.plist'}
    names.update(row[0]+'.stderr.txt' for row in split404_schema_rows(partition))
    return names


def split404_read_evidence(output, partition):
    require(output.is_dir() and not output.is_symlink(),'Evidence directory missing/linked')
    require({p.name for p in output.iterdir()}==split404_evidence_names(partition),'Unexpected/missing evidence file')
    result={}; total=0
    for path in output.iterdir():
        require(path.is_file() and not path.is_symlink(),'Evidence must be a regular file')
        raw=path.read_bytes(); total+=len(raw)
        require((len(raw)>0 or path.name.endswith('.stderr.txt')) and len(raw)<=LIMIT,'Empty/oversized evidence')
        result[path.name]=raw
    require(total <= 8*LIMIT,'Oversized partition artifact')
    return result


def split404_json(raw):
    require(len(raw)<=LIMIT,'Oversized JSON evidence')
    return json.loads(raw,object_pairs_hook=unique_object)


def split404_validate_schema_help(raw, kind):
    text = raw.decode('utf-8')
    require(kind in ('summary', 'tests') and
            'xcresulttool get test-results ' + kind + ' [--schema]' in text and
            '--schema-version' in text and 'Use --schema option' in text and '0.1.0' in text,
            'Unknown xcresulttool schema-help format')


def split404_validate_schema(raw, kind):
    """Narrow consumed contract observed from xcresulttool24757 schema0.1.0.

    Apple Summary declares two collection fields as direct object references;
    their actual JSON arrays are separately checked in validate_device_results.
    Unknown types, references, enumerations and modifiers remain rejected.
    """
    require(kind in ('summary','tests'),'Unknown requested schema model')
    data=split404_json(raw)
    require(type(data) is dict and type(data.get('schemas')) is dict,'Unknown xcresulttool JSON schema root')
    schemas=data['schemas']
    def obj(name):
        value=schemas.get(name)
        require(type(value) is dict and value.get('type')=='object' and type(value.get('properties')) is dict,'Unsupported schema object: '+name)
        require(set(value)<={'type','properties','required','description','title','additionalProperties'},'Unsupported schema object modifiers: '+name)
        required=value.get('required',[])
        require(type(required) is list and all(type(x) is str for x in required) and len(required)==len(set(required)) and set(required)<=set(value['properties']),'Invalid schema required fields')
        return value['properties'],set(required)
    def scalar(value,expected,enum=None,format=None):
        require(type(value) is dict and value.get('type')==expected,'Unsupported schema scalar type')
        allowed={'type','description','title'}
        if enum is not None:
            allowed.add('enum');require(value.get('enum')==enum,'Unsupported schema enum domain')
        if format is not None:
            allowed.add('format');require(value.get('format')==format,'Unsupported schema numeric format')
        require(set(value)<=allowed,'Unsupported schema scalar modifier')
        require(all(type(value[k]) is str for k in ('description','title') if k in value),'Invalid schema documentation field')
    def ref(value,name):
        require(value=={'$ref':'#/schemas/'+name},'Unbound consumed schema reference')
        return schemas.get(name)
    def array(value,name):
        require(type(value) is dict and value.get('type')=='array' and set(value)<={'type','items','description','title'},'Unsupported schema array')
        ref(value.get('items'),name);obj(name)
    def result(value):
        scalar(ref(value,'TestResult'),'string',['Passed','Failed','Skipped','Expected Failure','unknown'])
    fields={'deviceId','deviceName','architecture','modelName','platform','osVersion','osBuildNumber'}
    device,required=obj('Device')
    require(set(device)==fields and {'deviceId','deviceName','architecture','modelName','osVersion'}<=required,'Unsupported Device schema')
    for value in device.values():scalar(value,'string')
    config,required=obj('Configuration');require(set(config)=={'configurationId','configurationName'} and set(config)<=required,'Unsupported Configuration schema')
    for value in config.values():scalar(value,'string')
    if kind=='summary':
        counts={'passedTests','failedTests','skippedTests','expectedFailures'}
        row,required=obj('DeviceAndConfigurationSummary');require(set(row)==counts|{'device','testPlanConfiguration'} and set(row)<=required,'Unsupported summary row schema')
        ref(row['device'],'Device');ref(row['testPlanConfiguration'],'Configuration')
        for field in counts:scalar(row[field],'integer')
        summary,required=obj('Summary');needed=counts|{'totalTestCount','result','testFailures','devicesAndConfigurations'}
        require(needed<=set(summary) and needed<=required,'Incomplete Summary schema')
        for field in counts|{'totalTestCount'}:scalar(summary[field],'integer')
        result(summary['result'])
        ref(summary['testFailures'],'TestFailure');failure,_=obj('TestFailure');scalar(failure.get('failureText'),'string')
        ref(summary['devicesAndConfigurations'],'DeviceAndConfigurationSummary')
    else:
        tests,required=obj('Tests');refs={'devices':'Device','testPlanConfigurations':'Configuration','testNodes':'TestNode'}
        require(set(refs)<=required,'Incomplete Tests schema')
        for field,name in refs.items():array(tests.get(field),name)
        node,required=obj('TestNode');require({'nodeType','name','nodeIdentifier','result','children','durationInSeconds'}<=set(node) and {'nodeType','name'}<=required,'Incomplete TestNode schema')
        for field in ('name','nodeIdentifier'):scalar(node[field],'string')
        scalar(ref(node['nodeType'],'TestNodeType'),'string',['Test Plan','Unit test bundle','UI test bundle','Test Suite','Test Case','Device','Test Plan Configuration','Arguments','Repetition','Test Case Run','Failure Message','Source Code Reference','Attachment','Expression','Test Value','Runtime Warning'])
        result(node['result']);array(node['children'],'TestNode');scalar(node['durationInSeconds'],'number',format='double')

def split404_validate_simulator(evidence, simulator, toolchain):
    devices=split404_json(evidence['simulator-devices.json'])
    require(choose_simulator(devices)==simulator,'Selected simulator differs from raw available inventory')
    inventory=split404_json(evidence['simulator-runtimes.json'])
    require(isinstance(inventory,dict) and isinstance(inventory.get('runtimes'),list),'Unknown runtime inventory')
    matches=[row for row in inventory['runtimes'] if isinstance(row,dict) and row.get('identifier')==simulator['runtime']]
    require(len(matches)==1,'Missing/duplicate selected runtime')
    row=matches[0]
    require(row.get('isAvailable') is True and all(isinstance(row.get(k),str) and row[k] for k in ('identifier','version','buildversion','name')),'Incomplete actual runtime identity')
    require(re.fullmatch(r'[0-9]+(?:\.[0-9]+){1,2}',row['version']) and row['identifier']=='com.apple.CoreSimulator.SimRuntime.iOS-'+row['version'].replace('.','-'),'Runtime identifier/version mismatch')
    require(row['version']==toolchain['sdk_version'],'Unapproved SDK/runtime version difference')
    return {key:row[key] for key in ('identifier','version','buildversion','name')}


def split404_validate_device_results(summary, tests, count, simulator, runtime):
    require(isinstance(summary,dict) and isinstance(tests,dict),'Unknown XCTest raw documents')
    for key,value in [('totalTestCount',count),('passedTests',count),('failedTests',0),('skippedTests',0),('expectedFailures',0)]:
        require(type(summary.get(key)) is int and summary[key]==value,'Wrong raw summary count: '+key)
    require(summary.get('result')=='Passed' and summary.get('testFailures')==[],'Raw summary reports nonpassing/incomplete execution')
    rows=summary.get('devicesAndConfigurations')
    require(isinstance(rows,list) and len(rows)==1,'XCTest summary must have exactly one device/configuration')
    row=rows[0]
    require(isinstance(row,dict) and set(row)=={'device','testPlanConfiguration','passedTests','failedTests','skippedTests','expectedFailures'},'Unknown device/configuration summary fields')
    for key,value in [('passedTests',count),('failedTests',0),('skippedTests',0),('expectedFailures',0)]:
        require(type(row.get(key)) is int and row[key]==value,'Wrong device-specific count')
    device=row['device'];config=row['testPlanConfiguration']
    fields={'deviceId','deviceName','architecture','modelName','platform','osVersion','osBuildNumber'}
    require(isinstance(device,dict) and set(device)==fields and all(isinstance(v,str) and v for v in device.values()),'Unknown actual XCTest device schema')
    require(device['deviceId'].lower()==simulator['udid'].lower() and device['deviceName']==simulator['name'] and device['platform']=='iOS Simulator' and device['osVersion']==runtime['version'] and device['osBuildNumber']==runtime['buildversion'],'Executed device/OS differs from actual selected runtime')
    require(isinstance(config,dict) and set(config)=={'configurationId','configurationName'} and all(isinstance(v,str) and v for v in config.values()),'Unknown test-plan configuration')
    require(tests.get('devices')==[device] and tests.get('testPlanConfigurations')==[config],'Raw tests/summary device or configuration differs')


def split404_core_inventory(root):
    build=(root/'.build').resolve(strict=True)
    candidates={p.resolve(strict=True) for p in build.rglob('QuestifyCorePackageTests.xctest') if p.is_dir() and not p.is_symlink()}
    require(len(candidates)==1,'Expected exactly one freshly built Core test bundle')
    bundle=next(iter(candidates));require(bundle.is_relative_to(build),'Core test bundle escaped fresh build')
    ledger=split404_ledger(bundle)
    product={'configuration':SPLIT404_CONFIGS['core'],'bundle':bundle.name,'files':len(ledger),'sha256':split404_hash(ledger)}
    split404_validate_ledger(ledger,product);return product,ledger


def validate_split404_partition(receipt,expected,selection,evidence):
    require(type(receipt) is dict and type(receipt.get('version')) is int and receipt['version']==2
        and receipt.get('scope')=='split404-partition-only' and receipt.get('status')=='PASS','Not a split404 partition pass')
    partition=receipt.get('partition');require(partition in SPLIT404_PARTITIONS,'Unknown receipt partition')
    require(set(expected)==SPLIT404_ID_KEYS,'Incomplete trusted current identity')
    for key,value in expected.items():require(bool(value) and receipt.get(key)==value,'Partition identity differs: '+key)
    require(receipt.get('artifact_name')==split404_artifact_name(expected,partition),'Wrong artifact name')
    require(set(evidence)==split404_evidence_names(partition),'Missing/extra evidence for exact target partition')
    require(split404_json(evidence['receipt.json'])==receipt,'Receipt differs from artifact bytes')
    groups=split404_groups(selection,partition);require(len(groups)==1 and groups[0]['name']==partition,'Wrong target partition group')
    group=groups[0];total=len(group['methods'])
    require(all(type(receipt.get(k)) is int and receipt[k]==total for k in ('expected_count','actual_count')),'Wrong partition count')
    require(set(receipt.get('groups',{}))=={partition},'Wrong partition result groups')
    toolchain=receipt.get('toolchain',{})
    require(set(toolchain)==SPLIT404_TOOLCHAIN_KEYS and all(type(v) is str and v for v in toolchain.values()),'Incomplete toolchain')
    require(re.fullmatch(r'(?:arm64|x86_64)-apple-macosx[0-9]+(?:\.[0-9]+){0,2}',toolchain['host_triple']) is not None,'Unknown actual Core host target')
    require(all(re.fullmatch(r'[0-9]+(?:\.[0-9]+){1,2}',toolchain[k]) for k in ('sdk_version','host_sdk_version')),'Unknown actual SDK version')
    image=receipt.get('runner_image',{})
    require(set(image)=={'ImageOS','ImageVersion','RUNNER_ARCH'} and all(type(v) is str and v for v in image.values()),'Incomplete runner image')
    require(image['RUNNER_ARCH'] in ('ARM64','X64') and toolchain['host_triple'].startswith('arm64-' if image['RUNNER_ARCH']=='ARM64' else 'x86_64-'),'Host target differs from actual runner architecture')
    phases=split404_json(evidence['phase-times.json']);split404_validate_phases(phases,partition);split404_validate_worker_clock(receipt,phases)
    ledger=split404_json(evidence['products-ledger.json']);require(set(receipt.get('products',{}))==set(ledger)=={partition},'Wrong partition product set')
    product=receipt['products'][partition]
    require(product.get('configuration')==SPLIT404_CONFIGS[partition],'Wrong actual product configuration')
    split404_validate_ledger(ledger[partition],product)
    require(receipt.get('products_before')==receipt['products']==receipt.get('products_after'),'Products changed during selected tests')
    require(receipt.get('source_before')==receipt.get('source_after')=={k:expected[k] for k in ('source_sha','source_tree')},'Source changed during selected tests')
    if partition=='core':
        require(not set(receipt)&{'simulator','simulator_runtime','xcresulttool_version','result_bundle_path'},'Core-only receipt cannot claim simulator execution')
        provenance=split404_json(evidence['core-build-provenance.json'])
        require(type(provenance) is dict and type(provenance.get('version')) is int and type(provenance.get('returncode')) is int,'Noninteger Core build provenance status')
        require(provenance=={'version':1,'source_sha':expected['source_sha'],'source_tree':expected['source_tree'],
            'source_archive_sha256':expected['source_archive_sha256'],'target':'QuestifyCorePackageTests',
            'host_sdk_version':toolchain['host_sdk_version'],'host_sdk_path':toolchain['host_sdk_path'],'host_triple':toolchain['host_triple'],
            'argv':['swift','build','--build-tests','--sdk',toolchain['host_sdk_path'],'--triple',toolchain['host_triple']],
            'returncode':0},'Core build target/SDK/source provenance differs')
    else:
        simulator=receipt.get('simulator',{})
        require(set(simulator)=={'udid','name','runtime'} and re.fullmatch('[0-9A-Fa-f]{8}(?:-[0-9A-Fa-f]{4}){3}-[0-9A-Fa-f]{12}',simulator.get('udid','')) and simulator.get('name','').startswith('iPhone') and simulator.get('runtime','').startswith('com.apple.CoreSimulator.SimRuntime.iOS-'),'Incomplete simulator')
        split404_validate_capture(evidence,receipt,partition)
        for kind in ('summary','tests'):
            split404_validate_schema_help(evidence['xcresult-'+kind+'-help.txt'],kind)
            split404_validate_schema(evidence['xcresult-'+kind+'-schema.json'],kind)
        require(receipt.get('xcresulttool_version')==evidence['xcresult-version.txt'].decode().strip() and receipt['xcresulttool_version'].startswith('xcresulttool version '),'Missing actual xcresulttool version')
        runtime=split404_validate_simulator(evidence,simulator,toolchain)
        require(receipt.get('simulator_runtime')==runtime,'Runtime receipt differs from raw inventory')
        if partition=='app-unit':
            manifest=split404_json(evidence['app-unit-manifest.json'])
            require(manifest==product.get('manifest') and manifest.get('commit')==expected['source_sha'] and manifest.get('purpose')=='isolated-simulator-app-unit' and manifest.get('targets')=={'QuestifyAppUnitTests':product['xctestrun']} and manifest.get('toolchain')=={k:toolchain[k] for k in ('xcode','developer')},'AppUnit manifest identity differs')
            require(manifest.get('source_archive_sha256')==expected['source_archive_sha256'],'Wrong independently observed source archive')
            require(['questify-test-products.json','file',hashlib.sha256(evidence['app-unit-manifest.json']).hexdigest()] in ledger[partition],'Manifest differs from product ledger')
        else:
            config=split404_json(evidence['ui-config.json']);info=plistlib.loads(evidence['ui-info.plist'])
            require(info.get('QuestifyAPIBaseURL') in (None,'') and info.get('CFBundleSupportedPlatforms')==['iPhoneSimulator'],'Raw UI Info.plist unsafe')
            require(['Debug-iphonesimulator/Questify.app/Info.plist','file',hashlib.sha256(evidence['ui-info.plist']).hexdigest()] in ledger['ui'],'UI Info.plist differs from product ledger')
            require(not any(row[0].endswith('/embedded.mobileprovision') for row in ledger['ui']),'Provisioned UI product forbidden')
            require(config=={'QuestifyAPIBaseURL':'','CFBundleSupportedPlatforms':['iPhoneSimulator'],'embedded_mobileprovision':False},'Unsafe UI app configuration')
    hashes=receipt.get('evidence_sha256',{});require(set(hashes)==set(evidence)-{'receipt.json'},'Incomplete raw evidence digest set')
    for name,raw in evidence.items():
        if name!='receipt.json':require(hashes[name]==hashlib.sha256(raw).hexdigest(),'Changed raw evidence: '+name)
    entry=receipt['groups'][partition]
    require(entry.get('status')=='PASS' and entry.get('expected')==group['methods'] and type(entry.get('actual_count')) is int and entry['actual_count']==total,'Wrong group expected/actual count')
    if partition=='core':rows=validate_core_evidence(evidence['core.xml'],evidence['core-stdout.txt'],group['methods'],entry.get('returncode'))
    else:
        raw=split404_json(evidence[partition+'-tests.json']);rows=parse_xcresult(raw,group['target']);summary=split404_json(evidence[partition+'-summary.json'])
        split404_validate_device_results(summary,raw,total,simulator,runtime)
    require(entry.get('actual')==rows,'Receipt differs from reparsed actual native outcomes')
    validate_outcomes(rows,group['methods'],entry.get('returncode'));return rows


def aggregate_split404(selection,expected,artifacts,needs_result):
    require(needs_result=='success','Matrix has failed/cancelled/skipped/incomplete worker')
    names={split404_artifact_name(expected,p) for p in SPLIT404_PARTITIONS}
    require(isinstance(artifacts,dict) and set(artifacts)==names,'Missing/extra/stale-attempt artifact')
    all_rows=[];receipts=[]
    for partition in SPLIT404_PARTITIONS:
        name=split404_artifact_name(expected,partition);evidence=artifacts[name];receipt=split404_json(evidence['receipt.json'])
        require(receipt.get('partition')==partition and receipt.get('artifact_name')==name,'Artifact partition/name mismatch')
        all_rows.extend(validate_split404_partition(receipt,expected,selection,evidence));receipts.append(receipt)
    for key in ('toolchain','runner_image'):
        require(all(r[key]==receipts[0][key] for r in receipts),'Cross-runner '+key+' policy differs')
    simulator_receipts=receipts[1:]
    require(len({r['simulator']['udid'].lower() for r in simulator_receipts})==2,'AppUnit/UI require distinct actual simulator identities')
    for key in ('xcresulttool_version','simulator_runtime'):
        require(all(r[key]==simulator_receipts[0][key] for r in simulator_receipts),'Cross-simulator '+key+' policy differs')
    require(len({r['simulator']['runtime'] for r in simulator_receipts})==1,'Simulator runtime differs between workers')
    methods=[m for p in split404_layer(selection)['partitions'] for m in p['methods']]
    validate_outcomes(all_rows,methods,0);require(len(all_rows)==649,'No complete649 execution')
    return dict(expected,version=2,scope='split404-selected-native-diagnostic-only',status='PASS',expected_count=649,actual_count=649,
        counts={'core':340,'app-unit':244,'ui':65},actual=all_rows,partition_receipt_sha256={n:hashlib.sha256(v['receipt.json']).hexdigest() for n,v in artifacts.items()},
        coverage_boundary='Only exact selected404, not full required native gates or release admission')


def split404_schema_rows(partition,result=None):
    require(partition in ('app-unit','ui'), 'Core-only evidence never substitutes for simulator result schemas')
    group=partition
    rows=[row for row in merchant_schema_commands({group:result} if result is not None else {})
          if not row[0].startswith(('app-unit-','ui-')) or row[0].startswith(group+'-')]
    schemas=[('xcresult-'+kind+'-schema.json',['xcrun','xcresulttool','get','test-results',kind,'--schema','--schema-version','0.1.0'],1024*1024) for kind in ('summary','tests')]
    return rows[:3]+schemas+rows[3:]

def split404_capture_schema(root, output, partition, result_paths, receipt, seconds=90, *, skip_inventory=False):
    """Bounded acquisition is not admission. Even unsupported raw JSON is retained."""
    start=time.monotonic();deadline=start+min(90,max(0,seconds))
    destination=output/'schema-evidence'
    require(not destination.exists() and not destination.is_symlink(),'Schema evidence directory must be fresh')
    destination.mkdir(mode=0o700)
    group='app-unit' if partition=='app-unit' else 'ui'
    path=result_paths.get(group); verified=None
    if path is not None:
        path=Path(path)
        if (not path.is_symlink() and path.is_dir() and path.name==group+'.xcresult'
                and path.parent.resolve(strict=True)==output.resolve(strict=True)):
            verified=path
    manifest={'version':2,'purpose':'raw-apple-tool-schema-evidence-only',
        'native_test_result_authority':False,'partition':partition,'status':'PARTIAL_OR_FAILED',
        'identity':{k:receipt.get(k) for k in SPLIT404_ID_KEYS},'result_bundle_path':str(verified) if verified else None,
        'limits':{'total_seconds':90,'item_seconds':30,'total_bytes':48*1024*1024,'stderr_item_bytes':64*1024},
        'items':[],'retained_bytes':0}
    require(type(skip_inventory) is bool, 'Invalid initial inventory failure flag')
    for filename,command,limit in split404_schema_rows(partition,verified):
        if skip_inventory and filename in {'simulator-devices.json','simulator-runtimes.json'}:
            manifest['items'].append({'file':filename,'status':'NOT_RUN','reason':'Initial inventory failed; original streams retained separately without retry'})
            continue
        remaining=deadline-time.monotonic()
        if command is None or remaining<=0.6:
            manifest['items'].append({'file':filename,'status':'NOT_RUN','reason':'No readable actual result bundle' if command is None else 'Capture time exhausted'})
            continue
        available=48*1024*1024-128*1024-manifest['retained_bytes']
        if available<=64*1024:
            manifest['items'].append({'file':filename,'status':'NOT_RUN','reason':'Capture size exhausted'});continue
        item=merchant_capture_command(command,root,min(30,remaining),min(limit,available-64*1024))
        for stream in ('stdout','stderr'):
            raw=item.pop(stream);name=filename if stream=='stdout' else filename+'.stderr.txt'
            (destination/name).write_bytes(raw)
            item[stream]={'file':name,'byte_count':len(raw),'sha256':hashlib.sha256(raw).hexdigest()}
            manifest['retained_bytes']+=len(raw)
        item['file']=filename;manifest['items'].append(item)
    if len(manifest['items'])==9 and all(r['status']=='CAPTURED' for r in manifest['items']):manifest['status']='CAPTURED'
    manifest['wall_seconds']=time.monotonic()-start
    raw=(json.dumps(manifest,indent=2,ensure_ascii=True)+'\n').encode()
    require(len(raw)<=128*1024 and len(raw)+manifest['retained_bytes']<=48*1024*1024,'Capture manifest exceeds reserved limit')
    (destination/'manifest.json').write_bytes(raw)
    return manifest


def split404_validate_capture(evidence, receipt, partition):
    import math
    manifest=split404_json(evidence['schema-manifest.json'])
    require(isinstance(manifest,dict) and set(manifest)=={'version','purpose','native_test_result_authority','partition','status','identity','result_bundle_path','limits','items','retained_bytes','wall_seconds'},'Unknown capture manifest schema')
    require(type(manifest.get('version')) is int and manifest['version']==2 and
        manifest.get('purpose')=='raw-apple-tool-schema-evidence-only' and manifest.get('native_test_result_authority') is False and
        manifest.get('partition')==partition and manifest.get('status')=='CAPTURED','Incomplete/wrong acquisition manifest')
    require(manifest['identity']=={k:receipt[k] for k in SPLIT404_ID_KEYS},'Acquisition source/run/attempt differs')
    require(manifest['limits']=={'total_seconds':90,'item_seconds':30,'total_bytes':48*1024*1024,'stderr_item_bytes':64*1024},'Changed acquisition budget')
    group='app-unit' if partition=='app-unit' else 'ui';path=manifest['result_bundle_path']
    require(isinstance(path,str) and Path(path).is_absolute() and '..' not in Path(path).parts and
            Path(path).name==group+'.xcresult' and receipt.get('result_bundle_path')==path,'Acquisition result path not bound to executed command')
    expected=split404_schema_rows(partition,Path(path));items=manifest['items']
    require(isinstance(items,list) and [r.get('file') for r in items]==[r[0] for r in expected],'Missing/extra/duplicate acquisition item')
    retained=0
    for item,(filename,command,limit) in zip(items,expected):
        require(set(item)=={'argv','status','returncode','wall_seconds','observed_bytes','truncated','stdout','stderr','file'},'Unknown acquisition item fields')
        require(item['argv']==command and item['status']=='CAPTURED' and type(item['returncode']) is int and item['returncode']==0,'Wrong/incomplete acquisition command')
        require(type(item['wall_seconds']) in (float,int) and math.isfinite(item['wall_seconds']) and 0<=item['wall_seconds']<=30,'Unbounded acquisition item time')
        require(item['truncated']=={'stdout':False,'stderr':False} and set(item['observed_bytes'])=={'stdout','stderr'},'Truncated acquisition stream')
        for stream in ('stdout','stderr'):
            name=filename if stream=='stdout' else filename+'.stderr.txt';row=item[stream];raw=evidence[name]
            require(row=={'file':name,'byte_count':len(raw),'sha256':hashlib.sha256(raw).hexdigest()},'Raw capture stream identity differs')
            require(type(row['byte_count']) is int and len(raw)<=(limit if stream=='stdout' else 64*1024) and
                type(item['observed_bytes'][stream]) is int and item['observed_bytes'][stream]==len(raw),'Capture byte bound/truncation mismatch')
            retained+=len(raw)
    require(type(manifest['retained_bytes']) is int and manifest['retained_bytes']==retained and
        retained+len(evidence['schema-manifest.json'])<=48*1024*1024,'Total capture size differs')
    require(type(manifest['wall_seconds']) in (int,float) and math.isfinite(manifest['wall_seconds']) and
        0<=manifest['wall_seconds']<=90 and sum(r['wall_seconds'] for r in items)<=manifest['wall_seconds']+0.00001,'Invalid capture total clock')
    return manifest


def split404_record_command(output, stem, item, identity, *, result=None):
    """Keep bounded original command bytes even when execution/admission fails."""
    destination = output / 'command-evidence'
    destination.mkdir(exist_ok=True)
    require(destination.is_dir() and not destination.is_symlink(), 'Unsafe command evidence directory')
    record = {key: value for key, value in item.items() if key not in ('stdout', 'stderr')}
    record['identity'] = {key: identity[key] for key in SPLIT404_ID_KEYS if key in identity}
    for stream in ('stdout', 'stderr'):
        filename = stem + ('.json' if stream == 'stdout' and stem.startswith('inventory-') else '-stdout.txt' if stream == 'stdout' else '.stderr.txt' if stem.startswith('inventory-') else '-stderr.txt')
        raw = item[stream]
        (destination / filename).write_bytes(raw)
        record[stream] = {'file': filename, 'byte_count': len(raw), 'sha256': hashlib.sha256(raw).hexdigest()}
    if result is not None:
        record['result_path'] = str(result)
        record['result'] = {'file': 'core.xml', 'status': 'NOT_RUN', 'observed_bytes': 0,
                            'byte_count': 0, 'sha256': hashlib.sha256(b'').hexdigest(), 'truncated': False}
        raw = b''
        if result.is_file() and not result.is_symlink() and result.stat().st_nlink == 1:
            with result.open('rb') as stream: raw = stream.read(10 * 1024 * 1024 + 1)
            size = result.stat().st_size
            record['result'].update(status='CAPTURED' if size == len(raw) <= 10 * 1024 * 1024 else 'SIZE_LIMIT',
                                    observed_bytes=size, truncated=size > 10 * 1024 * 1024)
            raw = raw[:10 * 1024 * 1024]
            record['result'].update(byte_count=len(raw), sha256=hashlib.sha256(raw).hexdigest())
        (destination / 'core.xml').write_bytes(raw)
    return record


def split404_collect_core(job, group, command, seconds, result):
    require(result == job.output / 'core.xml' and not result.exists() and not result.is_symlink(),
            'Core XML must be a fresh exact output path')
    require(command == core_command(group, result)+['--sdk',job.receipt['toolchain']['host_sdk_path'],'--triple',job.receipt['toolchain']['host_triple']], 'Core command differs from exact selected identities')
    entry = job.receipt['groups']['core']; entry['status'] = 'RUNNING'; job.save()
    item = merchant_capture_command(command, job.root, min(seconds, job.deadline - time.monotonic()), 10 * 1024 * 1024)
    record = split404_record_command(job.output, 'core', item, job.receipt, result=result)
    write_json(job.output / 'command-evidence' / 'core-command.json', record)
    (job.output / 'core-stdout.txt').write_bytes(item['stdout'])
    entry.update(returncode=item['returncode'], transcript_sha256=hashlib.sha256(item['stdout']).hexdigest())
    try:
        require(item['status'] == 'CAPTURED' and item['truncated'] == {'stdout': False, 'stderr': False}
                and type(item['returncode']) is int and item['returncode'] == 0,
                'Core command failed; bounded stdout/stderr/XML retained')
        require(record['result']['status'] == 'CAPTURED', 'Missing or oversized Core XML; retained bounded diagnostics')
        raw = result.read_bytes()
        require(hashlib.sha256(raw).hexdigest() == record['result']['sha256'], 'Core XML changed after capture')
        rows = validate_core_evidence(raw, item['stdout'], group['methods'], item['returncode'])
        validate_outcomes(rows, group['methods'], item['returncode'])
        entry.update(actual=rows, actual_count=len(rows), result_sha256=hashlib.sha256(raw).hexdigest(), status='PASS')
        for line in item['stdout'].decode('utf-8', errors='replace').splitlines():
            if line.startswith('Test Case '): print(line, flush=True)
    except Exception as error:
        entry.update(status='FAIL', error=str(error))
        raise
    finally:
        job.save()


def split404_inventory(job):
    job.initial_inventory_incomplete = True
    documents = {}; records = []
    for kind in ('devices', 'runtimes'):
        command = ['xcrun', 'simctl', 'list', kind]
        if kind == 'devices': command.append('available')
        command.append('--json')
        item = merchant_capture_command(command, job.root, min(60, job.deadline - time.monotonic()), 2 * 1024 * 1024)
        record = split404_record_command(job.output, 'inventory-' + kind, item, job.receipt)
        records.append(record)
        write_json(job.output / 'command-evidence' / 'inventory-manifest.json',
                   {'version': 1, 'purpose': 'initial-simulator-inventory-command-diagnostics-only',
                    'native_test_result_authority': False, 'items': records,
                    'limits': {'item_seconds': 60, 'stdout_item_bytes': 2 * 1024 * 1024, 'stderr_item_bytes': 64 * 1024}})
        require(item['status'] == 'CAPTURED' and item['truncated'] == {'stdout': False, 'stderr': False}
                and type(item['returncode']) is int and item['returncode'] == 0,
                'Cannot observe simulator inventory; bounded initial stdout/stderr retained: ' + kind)
        raw = item['stdout']; (job.output / ('simulator-' + kind + '.json')).write_bytes(raw)
        documents['simulator-' + kind + '.json'] = raw
    simulator = choose_simulator(split404_json(documents['simulator-devices.json']))
    runtime = split404_validate_simulator(documents, simulator, job.receipt['toolchain'])
    job.receipt['simulator_runtime'] = runtime
    job.initial_inventory_incomplete = False
    return simulator


class Split404Diagnostic(Diagnostic):
    def __init__(self,root,output,selection,partition,preflight):
        require(partition in SPLIT404_PARTITIONS,'Unknown exact target partition')
        self.root,self.output,self.selection,self.partition=root,output,selection,partition
        self.schema_result_paths={};self.initial_inventory_incomplete=False;self.phases=read_json(preflight)
        require(set(self.phases)=={'checkout-initialization','python-validation','source-validation'},'Missing fresh preflight phases')
        start=self.phases['checkout-initialization']['started_monotonic']
        self.deadline=start+split404_layer(selection)['worker_cap_seconds']-split404_layer(selection)['finalization_reserve_seconds']
        self.receipt={'version':2,'scope':'split404-partition-only','status':'INCOMPLETE','partition':partition,
            'expected_count':sum(len(g['methods']) for g in split404_groups(selection,partition)),'actual_count':0,
            'groups':{g['name']:{'status':'NOT_RUN','expected':g['methods'],'actual_count':0,'actual':[]} for g in split404_groups(selection,partition)}}
    def phase(self,name,operation):
        require(name in split404_phase_names(self.partition) and name not in self.phases,'Duplicate/unknown phase')
        start=time.monotonic();code=1
        try:result=operation();code=0;return result
        finally:
            end=time.monotonic();self.phases[name]={'started_monotonic':start,'ended_monotonic':end,'wall_seconds':end-start,'returncode':code}
            write_json(self.output/'phase-times.json',self.phases)
    def run_command(self,name,command,seconds):
        def perform():
            code,_=self.command(command,seconds)
            require(type(code) is int and code==0,'Failed build/boot command: '+name)
        return self.phase(name,perform)
    def toolchain(self):
        observed=super().toolchain()
        info=json.loads(self.read(['swift','-print-target-info']),object_pairs_hook=unique_object)
        require(type(info) is dict and type(info.get('target')) is dict and type(info['target'].get('triple')) is str,'Missing actual Swift host target')
        observed.update(host_sdk_version=self.read(['xcrun','--sdk','macosx','--show-sdk-version']),
            host_sdk_path=self.read(['xcrun','--sdk','macosx','--show-sdk-path']),host_triple=info['target']['triple'])
        return observed
    def collect(self,group,command,seconds,result):
        if group['kind']=='swift':return split404_collect_core(self,group,command,seconds,result)
        positions=[i for i,value in enumerate(command) if value=='-resultBundlePath']
        require(len(positions)==1 and positions[0]+1<len(command) and str(command[positions[0]+1])==str(result),'Result bundle is not actual command path')
        require(result.parent==self.output and result.suffix=='.xcresult' and not result.exists() and not result.is_symlink(),'Result bundle must be fresh/local')
        self.schema_result_paths[group['name']]=result;self.receipt['result_bundle_path']=str(result)
        entry=self.receipt['groups'][group['name']];entry['status']='RUNNING';self.save()
        code,_=self.command(command,seconds);entry.update(returncode=code,status='EXECUTED_UNVALIDATED');self.save()
        require(type(code) is int and code==0,'Native command failed; raw capture is diagnostic only')
    def capture_schema(self):
        require(self.partition!='core','Core-only has no xcresult admission surface')
        return split404_capture_schema(self.root,self.output,self.partition,self.schema_result_paths,self.receipt,
            min(90,max(0,self.deadline-time.monotonic())),skip_inventory=self.initial_inventory_incomplete)
    def run(self):
        try:self.execute_partition()
        except BaseException as error:
            if self.partition!='core' and isinstance(error,Exception) and SPLIT404_ID_KEYS<=set(self.receipt):
                try:self.phase('schema-capture',self.capture_schema)
                except Exception as capture_error:print('SPLIT404_CAPTURE_FAILED '+str(capture_error)[:512],flush=True)
            raise
        if self.partition!='core':self.phase('schema-capture',self.capture_schema)
        self.receipt['status']='EXECUTED';self.save()
    def inventory(self):return split404_inventory(self)
    def scope(self):return verify_split404_scope(self.root,self.selection)
    def execute_partition(self):
        split404_require_admission(self.selection);runtime_environment(os.environ)
        identity=self.phase('scope-before',lambda:split404_identity(self.root,self.selection,self.scope()))
        scope={k:identity[k] for k in ('source_sha','source_tree')};self.receipt.update(identity)
        self.receipt['artifact_name']=split404_artifact_name(self.receipt,self.partition);self.receipt['source_before']=scope
        self.receipt['runner_image']={k:os.environ.get(k,'') for k in ('ImageOS','ImageVersion','RUNNER_ARCH')}
        self.receipt['toolchain']=self.phase('toolchain-before',self.toolchain);self.save()
        group=split404_groups(self.selection,self.partition)[0];budget=split404_layer(self.selection)['budget_seconds'];name=group['name']
        if name=='core':
            require(not (self.root/'.build').exists(),'Preexisting Core products forbidden')
            toolchain=self.receipt['toolchain'];build=['swift','build','--build-tests','--sdk',toolchain['host_sdk_path'],'--triple',toolchain['host_triple']]
            self.run_command('core-build',build,budget['core-build'])
            provenance=dict(version=1,source_sha=identity['source_sha'],source_tree=identity['source_tree'],source_archive_sha256=identity['source_archive_sha256'],
                target='QuestifyCorePackageTests',host_sdk_version=toolchain['host_sdk_version'],host_sdk_path=toolchain['host_sdk_path'],host_triple=toolchain['host_triple'],argv=build,returncode=0)
            write_json(self.output/'core-build-provenance.json',provenance)
            product,ledger=self.phase('products-before',lambda:split404_core_inventory(self.root))
            self.receipt['products']={'core':product};self.receipt['products_before']={'core':product};write_json(self.output/'products-ledger.json',{'core':ledger});self.save()
            require(self.phase('toolchain-after-build',self.toolchain)==toolchain,'Toolchain changed after Core build')
            result=self.output/'core.xml';command=core_command(group,result)+['--sdk',toolchain['host_sdk_path'],'--triple',toolchain['host_triple']]
            self.phase('core-test',lambda:self.collect(group,command,budget['core-test'],result))
            after,after_ledger=self.phase('products-after',lambda:split404_core_inventory(self.root))
            require((after,after_ledger)==(product,ledger),'Core bundle changed during selected tests');self.receipt['products_after']={'core':after}
        else:
            simulator=self.phase('simulator-inventory',self.inventory);self.receipt['simulator']=simulator;self.save()
            if name=='app-unit':
                self.run_command('app-build',[sys.executable,'-B','tools/build_simulator_keychain_host.py','--source-root',str(self.root),'--commit',identity['source_sha'],'--simulator',simulator['udid'],'--approve-ephemeral-simulator-host'],budget['app-build'])
                products=Path(os.environ['RUNNER_TEMP'])/'app-unit-linked/Products'
            else:
                derived=self.output/'ui-build'
                self.run_command('ui-build',['xcodebuild','-project','Questify.xcodeproj','-scheme','Questify','-configuration','Debug','-sdk','iphonesimulator','-destination','platform=iOS Simulator,id='+simulator['udid'],'-destination-timeout','60','-derivedDataPath',str(derived),'CODE_SIGNING_ALLOWED=NO','ONLY_ACTIVE_ARCH=NO','build-for-testing'],budget['ui-build'])
                products=derived/'Build/Products'
            run=None
            def inspect():
                nonlocal run
                run=select_xctestrun(products,group['target']);ledger=split404_ledger(products)
                product={'configuration':SPLIT404_CONFIGS[name],'xctestrun':run.name,'xctestrun_sha256':digest(run),'files':len(ledger),'sha256':split404_hash(ledger)}
                if name=='app-unit':
                    raw=(products/'questify-test-products.json').read_bytes();manifest=split404_json(raw)
                    (self.output/'app-unit-manifest.json').write_bytes(raw);product['manifest']=manifest
                    require(manifest.get('source_archive_sha256')==identity['source_archive_sha256'] and manifest.get('commit')==identity['source_sha'] and manifest.get('targets')=={'QuestifyAppUnitTests':run.name} and manifest.get('purpose')=='isolated-simulator-app-unit' and manifest.get('toolchain')=={k:self.receipt['toolchain'][k] for k in ('xcode','developer')},'Wrong actual AppUnit source/products')
                else:
                    app=products/'Debug-iphonesimulator/Questify.app';info_raw=(app/'Info.plist').read_bytes();info=plistlib.loads(info_raw);(self.output/'ui-info.plist').write_bytes(info_raw)
                    require(info.get('QuestifyAPIBaseURL') in (None,'') and info.get('CFBundleSupportedPlatforms')==['iPhoneSimulator'] and not (app/'embedded.mobileprovision').exists(),'Unsafe UI products')
                    write_json(self.output/'ui-config.json',{'QuestifyAPIBaseURL':'','CFBundleSupportedPlatforms':['iPhoneSimulator'],'embedded_mobileprovision':False})
                return {name:product},{name:ledger}
            products_before,ledger=self.phase('products-before',inspect);self.receipt.update(products=products_before,products_before=products_before)
            write_json(self.output/'products-ledger.json',ledger);self.save()
            require(self.phase('toolchain-after-build',self.toolchain)==self.receipt['toolchain'],'Toolchain changed after build')
            self.run_command('boot',['xcrun','simctl','bootstatus',simulator['udid'],'-b'],budget['boot'])
            result=self.output/(name+'.xcresult');phase='app-test' if name=='app-unit' else 'ui-test'
            self.phase(phase,lambda:self.collect(group,xcode_test_command(group,run,simulator['udid'],result),budget[phase],result))
            after,after_ledger=self.phase('products-after',inspect);require(after==products_before and after_ledger==ledger,'Native products changed during tests');self.receipt['products_after']=after
        self.receipt['source_after']=self.phase('scope-after',self.scope);require(self.receipt['source_after']==scope,'Source changed during execution')
        require(self.phase('toolchain-after',self.toolchain)==self.receipt['toolchain'],'Toolchain changed during execution')
        self.receipt['status']='EXECUTED_UNVALIDATED';self.save()


def split404_report(output,evidence,selection,root,summary=None):
    start=time.monotonic();receipt=read_json(output/'receipt.json')
    require(receipt.get('status')=='EXECUTED','Partition not fully executed; cannot emit PASS')
    expected=split404_identity(root,selection);partition=receipt['partition'];groups=split404_groups(selection,partition)
    phases=read_json(output/'phase-times.json');final_deadline=phases['checkout-initialization']['started_monotonic']+2700-30
    documents={}
    if partition!='core':
        capture=output/'schema-evidence';raw_names={r[0] for r in split404_schema_rows(partition)};raw_names|={n+'.stderr.txt' for n in tuple(raw_names)}
        require(capture.is_dir() and not capture.is_symlink() and {p.name for p in capture.iterdir()}==raw_names|{'manifest.json'},'Missing/extra capture evidence')
        for path in capture.iterdir():
            require(path.is_file() and not path.is_symlink() and path.stat().st_size<=LIMIT,'Unsafe capture file')
            documents['schema-manifest.json' if path.name=='manifest.json' else path.name]=path.read_bytes()
        split404_validate_capture(documents,receipt,partition)
        for kind in ('summary','tests'):
            split404_validate_schema_help(documents['xcresult-'+kind+'-help.txt'],kind)
            split404_validate_schema(documents['xcresult-'+kind+'-schema.json'],kind)
        receipt['xcresulttool_version']=documents['xcresult-version.txt'].decode().strip()
        runtime=split404_validate_simulator(documents,receipt['simulator'],receipt['toolchain'])
        require(runtime==receipt['simulator_runtime'],'Simulator changed since selection')
        reread_deadline=min(final_deadline,time.monotonic()+60)
        group=groups[0];path=output/(partition+'.xcresult')
        require(path.is_dir() and not path.is_symlink() and str(path)==receipt['result_bundle_path'],'Report result differs from actual command')
        for part in ('summary','tests'):
            item=merchant_capture_command(['xcrun','xcresulttool','get','test-results',part,'--path',str(path),'--compact'],root,min(30,reread_deadline-time.monotonic()),10*1024*1024)
            require(item['status']=='CAPTURED' and type(item['returncode']) is int and item['returncode']==0,'Cannot re-extract bounded actual xcresult')
            require(split404_json(item['stdout'])==split404_json(documents[partition+'-'+part+'.json']),'Re-extracted xcresult differs')
        raw=split404_json(documents[partition+'-tests.json']);rows=parse_xcresult(raw,group['target'])
        split404_validate_device_results(split404_json(documents[partition+'-summary.json']),raw,len(group['methods']),receipt['simulator'],runtime)
        entry=receipt['groups'][partition];validate_outcomes(rows,group['methods'],entry.get('returncode'));entry.update(status='PASS',actual=rows,actual_count=len(rows))
    else:
        require(not (output/'schema-evidence').exists() and set(receipt['groups'])=={'core'},'Core-only cannot substitute missing App/UI schema evidence')
        group=groups[0];entry=receipt['groups']['core'];rows=validate_core_evidence((output/'core.xml').read_bytes(),(output/'core-stdout.txt').read_bytes(),group['methods'],entry.get('returncode'))
        require(entry.get('status')=='PASS' and entry.get('actual')==rows,'Core outcome differs from actual retained execution')
    receipt['actual_count']=sum(g['actual_count'] for g in receipt['groups'].values())
    end=time.monotonic();require(end<=final_deadline,'Final report exhausted worker budget')
    phases['report']={'started_monotonic':start,'ended_monotonic':end,'wall_seconds':end-start,'returncode':0};documents['phase-times.json']=(encode(phases)+'\n').encode()
    for name in split404_evidence_names(partition)-set(documents)-{'receipt.json'}:
        path=output/name;require(path.is_file() and not path.is_symlink() and path.stat().st_nlink==1 and path.stat().st_size<=LIMIT,'Unsafe result evidence')
        documents[name]=path.read_bytes()
    receipt['status']='PASS';receipt['worker_clock']=split404_worker_clock(phases);receipt['evidence_sha256']={n:hashlib.sha256(raw).hexdigest() for n,raw in documents.items()}
    documents['receipt.json']=(encode(receipt)+'\n').encode();validate_split404_partition(receipt,expected,selection,documents)
    evidence.mkdir()
    for name,raw in documents.items():(evidence/name).write_bytes(raw)
    end=time.monotonic();require(end<=final_deadline,'Evidence serialization exhausted finalization budget')
    phases['report'].update(ended_monotonic=end,wall_seconds=end-start);receipt['worker_clock']=split404_worker_clock(phases)
    documents['phase-times.json']=(encode(phases)+'\n').encode();receipt['evidence_sha256']['phase-times.json']=hashlib.sha256(documents['phase-times.json']).hexdigest();documents['receipt.json']=(encode(receipt)+'\n').encode()
    validate_split404_partition(receipt,expected,selection,documents)
    for name in ('phase-times.json','receipt.json'):(evidence/name).write_bytes(documents[name])
    text='current649 partition '+partition+': PASS '+str(receipt['actual_count'])+'; aggregate404 still required\n';print(text)
    if summary:
        with summary.open('a') as stream:stream.write(text)


def split404_preflight(root,selection,output,start_file):
    split404_require_admission(selection)
    import math
    start=float(start_file.read_text().strip());now=time.monotonic()
    require(math.isfinite(start) and 0<=start<=now,'Invalid job-entry monotonic marker')
    phases={'checkout-initialization':{'started_monotonic':start,'ended_monotonic':now,'wall_seconds':now-start,'returncode':0}}
    for name,operation in [('python-validation',lambda:execute([sys.executable,'-B','-m','unittest','-v','tools.tests.test_targeted_native.Split404PartitionProtocol','tools.tests.test_targeted_native.Split404CommandDiagnostics','tools.tests.test_targeted_native.Club87SourceBoundary.test_current87_and_old71_default_domains_are_distinct','tools.tests.test_targeted_native.Club87SourceBoundary.test_complete87_new16_and_published_merchant6_preserved_with_exclusive_partition'],root,max(1,start+2460-time.monotonic()))[0]),('source-validation',lambda:validate_split404_selection(selection,root))]:
        a=time.monotonic();code=1
        try:
            result=operation()
            if name=='python-validation':require(type(result) is int and result==0,'Direct current649 diagnostic controls failed')
            code=0
        finally:
            b=time.monotonic();phases[name]={'started_monotonic':a,'ended_monotonic':b,'wall_seconds':b-a,'returncode':code};write_json(output,phases)


def split404_observe_command(phase, start_file, returncode, summary=None):
    """Outer command/transfer observation, logged after its actual completion.

    An immutable artifact cannot contain its own future upload duration. Upload
    and complete report-command observations are therefore retained in the same
    worker's official log/step summary; upload success is also required by needs.
    """
    import math
    require(phase in {'report-command','artifact-upload','artifact-download'},'Unknown outer observation')
    start=float(start_file.read_text());end=time.monotonic()
    require(math.isfinite(start) and 0<=start<=end and type(returncode) is int,'Invalid outer clock')
    observation={'phase':phase,'started_monotonic':start,'ended_monotonic':end,'wall_seconds':end-start,
        'returncode':returncode,'source_sha':os.environ.get('GITHUB_SHA',''),
        'run_id':os.environ.get('GITHUB_RUN_ID',''),'run_attempt':os.environ.get('GITHUB_RUN_ATTEMPT','')}
    text='SPLIT404_OUTER_PHASE '+encode(observation)+'\n';print(text,flush=True)
    if summary:
        with summary.open('a') as stream:stream.write(text)
    return observation


def split404_main():
    parser=argparse.ArgumentParser(description='Strict independent current649 three-partition protocol')
    parser.add_argument('action',choices=['validate','preflight','run-partition','report-partition','aggregate','record-observation'])
    parser.add_argument('--source-root',type=Path,default=ROOT);parser.add_argument('--partition',choices=SPLIT404_PARTITIONS)
    for flag in ('output','evidence','artifacts','preflight','start-file','summary'):parser.add_argument('--'+flag,type=Path)
    parser.add_argument('--needs-result');parser.add_argument('--phase');parser.add_argument('--returncode',type=int,default=0)
    args=parser.parse_args();root=args.source_root.absolute();selection=read_json(root/SPLIT404_PATHS[1])
    if args.action=='validate':
        validate_split404_selection(selection,root)
        print('Static current649=340/244/65, target-disjoint340/244/65; original339 controls preserved. Apple NOT_RUN.')
        return 0
    split404_require_admission(selection)
    if args.action=='record-observation':
        require(args.start_file is not None,'Observation clock required')
        split404_observe_command(args.phase,args.start_file,args.returncode,args.summary);return 0
    if args.action=='preflight':
        require(args.output is not None and args.start_file is not None,'Preflight paths required')
        split404_preflight(root,selection,args.output,args.start_file);return 0
    if args.action=='aggregate':
        require(args.artifacts is not None and args.output is not None,'Aggregate paths required')
        require(args.start_file is not None,'Download observation clock required')
        download=split404_observe_command('artifact-download',args.start_file,0,args.summary)
        expected=split404_identity(root,selection)
        require(args.artifacts.is_dir() and not args.artifacts.is_symlink(),'Missing artifact root')
        names={split404_artifact_name(expected,p):p for p in SPLIT404_PARTITIONS}
        require({p.name for p in args.artifacts.iterdir()}==set(names),'Downloaded artifact set not exact current run/attempt')
        documents={name:split404_read_evidence(args.artifacts/name,part) for name,part in names.items()}
        receipt=aggregate_split404(selection,expected,documents,args.needs_result);receipt['artifact_download_observation']=download;write_json(args.output,receipt)
        text='current649 selected diagnostic: PASS 649=Core340+AppUnit244+UI65. Full required native gates remain separate.\n'
        print(text)
        if args.summary:
            with args.summary.open('a') as stream:stream.write(text)
        return 0
    require(args.partition is not None and args.output is not None,'Exact partition/output required')
    temp=Path(os.environ['RUNNER_TEMP']).resolve(strict=True);output=args.output.absolute()
    require(output.parent.resolve(strict=True)==temp and not output.is_symlink(),'Output must be direct runner-temp child')
    if args.action=='report-partition':
        require(args.evidence is not None and args.evidence.parent.resolve(strict=True)==temp and not args.evidence.is_symlink(),'Fresh direct evidence directory required')
        split404_report(output,args.evidence,selection,root,args.summary);return 0
    require(args.preflight is not None,'Full preflight evidence required');output.mkdir()
    job=Split404Diagnostic(root,output,selection,args.partition,args.preflight);job.save()
    try:job.run()
    except BaseException as error:
        job.receipt.update(status='FAIL' if isinstance(error,Exception) else 'INCOMPLETE',error=str(error));job.save();raise
    return 0




# CLUB87_LAYER_END
if __name__ == '__main__':
    raise SystemExit(split404_main())
